async function fetchJSON(url) {
    const res = await fetch(url);
    return res.json();
}

function fillSelect(select, rows, labelKey, valueKey) {
    select.innerHTML = "";
    rows.forEach((row) => {
        const opt = document.createElement("option");
        opt.value = row[valueKey];
        opt.textContent = row[labelKey];
        select.appendChild(opt);
    });
}

async function loadCombos() {
    const [cats, prios, estados] = await Promise.all([
        fetchJSON("api.php?c=categoria&m=list"),
        fetchJSON("api.php?c=prioridad&m=list"),
        fetchJSON("api.php?c=estado&m=list"),
    ]);

    fillSelect(document.getElementById("categoria_id"), cats.data || [], "nombre", "id");
    fillSelect(document.getElementById("prioridad_id"), prios.data || [], "nombre", "id");
    fillSelect(document.getElementById("estado_id"), estados.data || [], "nombre", "id");
}

function renderTickets(list) {
    const container = document.getElementById("tickets-list");
    container.innerHTML = "";
    list.forEach((t) => {
        const item = document.createElement("div");
        item.className = "ticket-item";
        item.innerHTML = `
            <h3>${t.codigo} - ${t.titulo}</h3>
            <div class="ticket-meta">Usuario: ${t.usuario_id} | Estado: ${t.estado_id}</div>
            <div>${t.descripcion}</div>
        `;
        container.appendChild(item);
    });
}

async function loadTickets() {
    const data = await fetchJSON("api.php?c=ticket&m=list");
    renderTickets(data.data || []);
}

document.addEventListener("DOMContentLoaded", async () => {
    await loadCombos();
    await loadTickets();

    document.getElementById("refresh-btn").addEventListener("click", loadTickets);

    document.getElementById("ticket-form").addEventListener("submit", async (e) => {
        e.preventDefault();
        const form = e.target;
        const formData = new FormData(form);

        formData.append("codigo", "TCK-" + Date.now());

        const res = await fetch("api.php?c=ticket&m=create", {
            method: "POST",
            body: formData,
        });
        const data = await res.json();
        document.getElementById("form-message").textContent = data.message || "";

        if (data.status) {
            form.reset();
            await loadTickets();
        }
    });
});
```

