        item.className = 'item'; 
        const title = document.createElement('h3'); 
        title.textContent = row.nombre; 
        const meta = document.createElement('p'); 
        meta.textContent = 'Correo: ' + row.email + ' - Rol ID: ' + row.rol_id + ' - Activo: ' + (row.activo == 1 ? 'Si' : 'No'); 
