:root {  
    --bg: #1f3556;  
    --panel: #ffffff;  
    --accent: #3b82f6;  
    --text: #0f172a;  
    --muted: #64748b;  
    --line: #e2e8f0;  
}  
 
* {  
    box-sizing: border-box;  
}  
 
body {  
    margin: 0;  
    font-family: Trebuchet MS, Segoe UI, sans-serif;  
    background: radial-gradient(circle at top, #4b6cb7, var(--bg));  
    color: var(--text);  
    min-height: 100vh;  
} 
 
.page {  
    max-width: 1100px;  
    margin: 0 auto;  
    padding: 32px 20px 60px;  
    display: grid;  
    gap: 24px;  
}  
 
.page-header {  
    display: flex;  
    flex-wrap: wrap;  
    align-items: center;  
    justify-content: space-between;  
    gap: 16px;  
    color: #ffffff;  
}  
 
.page-header h1 {  
    margin: 0 0 6px;  
    font-size: 2rem;  
}  
 
.page-header p {  
    margin: 0;  
    color: #e2e8f0;  
}  
 
.card {  
    background: var(--panel);  
    border-radius: 16px;  
    padding: 24px;  
    box-shadow: 0 20px 35px rgba(15, 23, 42, 0.2);  
    display: grid;  
    gap: 16px;  
}  
 
.grid {  
    display: grid;  
    grid-template-columns: repeat(2, minmax(0, 1fr));  
    gap: 16px;  
}  
 
label {  
    display: grid;  
    gap: 6px;  
    font-weight: 600;  
    font-size: 0.95rem;  
}  
 
input,  
select,  
textarea {  
    width: 100%;  
    padding: 10px 12px;  
    border-radius: 10px;  
    border: 1px solid var(--line);  
    font-size: 1rem;  
}  
 
textarea {  
    resize: vertical;  
} 
 
.actions {  
    display: flex;  
    flex-wrap: wrap;  
    align-items: center;  
    gap: 12px;  
}  
 
.message {  
    color: var(--muted);  
    font-size: 0.95rem;  
}  
 
.list-header {  
    display: flex;  
    align-items: center;  
    justify-content: space-between;  
}  
 
.list {  
    display: grid;  
    gap: 12px;  
}  
 
.ticket-item {  
    border: 1px solid var(--line);  
    border-radius: 12px;  
    padding: 14px;  
    display: grid;  
    gap: 6px;  
}  
 
.ticket-item h3 {  
    margin: 0;  
    font-size: 1.05rem;  
}  
 
.ticket-meta {  
    color: var(--muted);  
    font-size: 0.9rem;  
}  
 
.btn {  
    display: inline-flex;  
    align-items: center;  
    justify-content: center;  
    padding: 10px 16px;  
    border-radius: 10px;  
    border: 1px solid var(--line);  
    background: #ffffff;  
    color: #0f172a;  
    text-decoration: none;  
    font-weight: 600;  
    cursor: pointer;  
}  
 
.btn.primary {  
    background: var(--accent);  
    border-color: var(--accent);  
    color: #ffffff;  
}  
 
.btn.ghost {  
    background: #f8fafc;  
}  
 
@media (max-width: 720px) {  
    .grid {  
        grid-template-columns: 1fr;  
    }  
} 
.layout { 
    display: grid; 
    grid-template-columns: 240px 1fr; 
    min-height: 100vh; 
} 
 
.sidebar { 
    background: rgba(15, 23, 42, 0.95); 
    color: #f8fafc; 
    padding: 24px 18px; 
    display: flex; 
    flex-direction: column; 
    gap: 18px; 
} 
 
.brand { 
    font-size: 1.15rem; 
    font-weight: 700; 
    letter-spacing: 1px; 
} 
 
.nav { 
    display: grid; 
    gap: 8px; 
} 
 
.nav-link { 
    display: block; 
    padding: 10px 12px; 
    border-radius: 10px; 
    text-decoration: none; 
    color: #e2e8f0; 
    font-weight: 600; 
} 
 
.nav-link:hover { 
    background: rgba(59, 130, 246, 0.25); 
    color: #ffffff; 
} 
 
.nav-link.logout { 
    margin-top: auto; 
    border: 1px solid rgba(248, 250, 252, 0.2); 
} 
 
@media (max-width: 900px) { 
    .layout { 
        grid-template-columns: 1fr; 
    } 
    .sidebar { 
        position: static; 
        height: auto; 
        flex-direction: row; 
        flex-wrap: wrap; 
    } 
    .nav { 
        width: 100%; 
        grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); 
    } 
    .nav-link.logout { 
        margin-top: 0; 
    } 
}

